import {
  _decorator, Component, Node, UITransform, Sprite, SpriteFrame, Label, Button,
  Graphics, Mask, Color, Vec2, Vec3, Rect, Size, JsonAsset, EditBox,
  SafeArea, Widget, BlockInputEvents, game, Game, input, Input, EventTouch,
  view, sys, isValid, native, Layers,
} from 'cc';
import {
  GameSession, GameLayout, StickerPlacement, PlacementTicket, SessionSnapshot,
  createLayoutDraft, patchStickerDraft, reorderDraft, validateLayout,
} from '../../core/GameSession';
import {
  Point2, Bounds, CameraPose, clamp, smooth, lerp, transformedPoint, inversePoint,
  transformedBounds, cameraContentBounds, fitCamera, clampCameraToScene, sourceToBoard, boardToSource, pressStrip, pickupStrip,
  FixedAttachment, fixedWorldTransform,
} from './TheatreGeometry';
import { validateTheatreDraft } from './TheatreLayoutGuard';
import { validateRenderableLayout } from '../../core/RenderableLayout';
import { AlphaMask, alphaAt, pickVisibleSticker } from './TheatreHitTest';
import { completeSourceFrame } from './TheatreSourceFrame';

const { ccclass, property } = _decorator;

/** Injected before start(); storage carries JSON text, never parsed objects. */
export interface TheatreRuntimeServices {
  loadJson(path: string): Promise<JsonAsset>;
  loadSpriteFrame(path: string): Promise<SpriteFrame>;
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

type ImagePart = {
  partId: string; file: string; assetKey?: string; offset: Point2;
  sourceSize: { width: number; height: number }; placementOrder: number; layerIndex: number;
};
type FixedImage = {
  fixedId: string; file: string; assetKey: string; position: Point2; sourceSize: { width: number; height: number };
  scale: number; rotation: number; anchor: Point2; requiresAssetIds: string[];
  placementOrder: number; layerIndex: number;
  attachment?: FixedAttachment;
};
type BasePatch = { patchId: string; assetKey: string; position: Point2;
  sourceSize: { width: number; height: number }; size: { width: number; height: number } };
type SceneData = { width: number; height: number; baseAssetKey: string; basePatches?: BasePatch[] };
type Motion = { duration: number; elapsed: number; step: (progress: number) => void; finish: (ok: boolean) => void };
type Strip = { node: Node; pixelX: number; width: number; frame: SpriteFrame };
type Paper = { root: Node; strips: Strip[]; sourceSize: { width: number; height: number } };
type Gesture = { id: number; kind: 'card' | 'target' | 'edit' | 'pan'; start: Point2; last: Point2;
  stickerId?: string; startPosition?: Point2; moved: boolean; cameraStart?: CameraPose };

const PAPER = new Color(244, 237, 219);
const INK = new Color(78, 53, 39);
const GOLD = new Color(183, 137, 66);
const MUTED = new Color(128, 108, 85);
const LEVEL_LABEL: Record<string, string> = { L1: '大件打底', L2: '补齐主体', L3: '叠加细节' };

/**
 * Cocos Creator 3.8.x component source. Mount below a 2D Canvas.
 * PNGs stay immutable. Paper strips crop SpriteFrame UVs at runtime only.
 * All placed parts are direct children of one world root in global painter order.
 */
@ccclass('TheatreGame')
export class TheatreGame extends Component {
  private runtime: TheatreRuntimeServices | null = null;
  private bootStarted = false;

  configureRuntime(runtime: TheatreRuntimeServices): void {
    if (this.bootStarted) throw new Error('运行服务必须在剧院组件启动前注入');
    this.runtime = runtime;
  }

  private runtimeServices(): TheatreRuntimeServices {
    if (!this.runtime) throw new Error('剧院组件缺少已初始化的运行服务');
    return this.runtime;
  }

  @property(JsonAsset)
  layoutAsset: JsonAsset | null = null;

  @property({ tooltip: 'resources 下的关卡 JSON，无扩展名；或直接拖入 layoutAsset' })
  layoutResource = 'theatre/theatre-layout';

  @property({ tooltip: 'resources 下的资源前缀' })
  resourcePrefix = 'theatre';

  @property({ tooltip: '资源前缀内的镊子 PNG 路径，无扩展名' })
  tweezersResource = 'ui/tweezers';

  private layout!: GameLayout;
  private sourceLayout!: GameLayout;
  private session!: GameSession;
  private draft!: GameLayout;
  private frames = new Map<string, SpriteFrame>();
  private loadedAssets: (SpriteFrame | JsonAsset)[] = [];
  private ownedFrames = new Set<SpriteFrame>();
  private sceneNodes = new Map<string, Node>();
  private motions = new Set<Motion>();
  private unsubscribe: (() => void) | null = null;
  private root!: Node;
  private ui!: Node;
  private board!: Node;
  private world!: Node;
  private effects!: Node;
  private overlay!: Node;
  private tray!: Node;
  private header!: Node;
  private status!: Label;
  private subtitle!: Label;
  private hint!: Label;
  private count!: Label;
  private progressBar!: Graphics;
  private shadow: Node | null = null;
  private ghost: Paper | null = null;
  private tool: Node | null = null;
  private toolFrame: SpriteFrame | null = null;
  private hitMasks = new Map<string, AlphaMask>();
  private pointer: Point2 = { x: 0, y: 0 };
  private pressPapers: { paper: Paper; owner: StickerPlacement; part: ImagePart }[] = [];
  private camera: CameraPose = { x: 0, y: 0, scale: 1 };
  private boardSize = { width: 1, height: 1 };
  private viewWidth = 390;
  private viewHeight = 844;
  private unit = 1;
  private page = 0;
  private editing = false;
  private editId: string | null = null;
  private busy = false;
  private overview = false;
  private suspended = false;
  private alive = true;
  private booted = false;
  private generation = 0;
  private gesture: Gesture | null = null;
  private modal: Node | null = null;
  private buttons = new Map<string, Button>();

  onEnable(): void {
    game.on(Game.EVENT_HIDE, this.onHide, this);
    game.on(Game.EVENT_SHOW, this.onShow, this);
    view.on('canvas-resize', this.relayout, this);
    view.on('design-resolution-changed', this.relayout, this);
    input.on(Input.EventType.TOUCH_START, this.onTouchStart, this);
    input.on(Input.EventType.TOUCH_MOVE, this.onTouchMove, this);
    input.on(Input.EventType.TOUCH_END, this.onTouchEnd, this);
    input.on(Input.EventType.TOUCH_CANCEL, this.onTouchCancel, this);
    if (this.booted) {
      this.suspended = false;
      this.busy = false;
      this.refresh();
      if (this.session.getSnapshot().phase === 'transitioning') void this.runTour();
    }
  }

  start(): void { this.bootStarted = true; void this.boot(); }

  onDisable(): void {
    // A background/scene switch may happen before TOUCH_END commits the edit gesture.
    if (this.booted && this.editing) this.persistDraft();
    game.off(Game.EVENT_HIDE, this.onHide, this);
    game.off(Game.EVENT_SHOW, this.onShow, this);
    view.off('canvas-resize', this.relayout, this);
    view.off('design-resolution-changed', this.relayout, this);
    input.off(Input.EventType.TOUCH_START, this.onTouchStart, this);
    input.off(Input.EventType.TOUCH_MOVE, this.onTouchMove, this);
    input.off(Input.EventType.TOUCH_END, this.onTouchEnd, this);
    input.off(Input.EventType.TOUCH_CANCEL, this.onTouchCancel, this);
    this.generation++;
    this.cancelMotions();
    if (this.booted) {
      this.session.cancelPlacement();
      this.session.cancelSelection();
      this.persist();
      this.clearPaper();
      this.gesture = null;
    }
  }

  onDestroy(): void {
    this.alive = false;
    this.generation++;
    this.cancelMotions();
    this.unsubscribe?.();
    this.unsubscribe = null;
    if (this.root && isValid(this.root)) this.root.destroy();
    for (const frame of this.ownedFrames) if (isValid(frame)) frame.destroy();
    this.ownedFrames.clear();
    for (const asset of this.loadedAssets) if (isValid(asset)) asset.decRef();
    this.loadedAssets.length = 0;
    this.frames.clear();
  }

  update(dt: number): void {
    if (this.suspended) return;
    for (const motion of [...this.motions]) {
      motion.elapsed += Math.min(Math.max(0, dt), 0.06);
      const progress = clamp(motion.elapsed / motion.duration, 0, 1);
      motion.step(progress);
      if (progress >= 1) { this.motions.delete(motion); motion.finish(true); }
    }
  }

  private async boot(): Promise<void> {
    try {
      this.buildRoot();
      const loading = this.makeLabel(this.ui, '剧场贴纸\n正在展开素材…', 24, 340, 100);
      const asset = this.layoutAsset ?? await this.loadJson(this.layoutResource);
      if (!this.alive || !isValid(this.node)) return;
      const errors = validateRenderableLayout(asset.json);
      if (errors.length) throw new Error(errors.join('\n'));
      this.sourceLayout = createLayoutDraft(asset.json as GameLayout);
      this.layout = createLayoutDraft(this.sourceLayout);
      try {
        const active = this.runtimeServices().getItem(`theatre-active-layout:${this.layout.sceneId}`);
        if (active) {
          const parsed = JSON.parse(active) as GameLayout;
          if (parsed.sourceLayoutRevision === this.sourceLayout.layoutRevision && this.isKnownDraft(parsed)) this.layout = parsed;
        }
      } catch { /* The source JSON remains authoritative if an active draft is corrupt. */ }
      this.draft = createLayoutDraft(this.layout);
      this.session = new GameSession(this.layout);
      const paths = new Set<string>([this.scene(this.layout).baseAssetKey]);
      for (const patch of this.scene(this.layout).basePatches ?? []) paths.add(patch.assetKey);
      for (const sticker of this.layout.stickers) {
        paths.add(String(sticker.file));
        for (const part of this.parts(sticker)) paths.add(part.file);
      }
      for (const fixed of this.fixed(this.layout)) paths.add(fixed.file);
      // A bounded loader keeps resource decoding from spiking on phones.
      const queue = [...paths]; let completed = 0;
      await Promise.all(Array.from({ length: Math.min(6, queue.length) }, async () => {
        while (queue.length && this.alive) {
          const path = queue.shift()!;
          await this.loadFrame(path);
          completed++;
          if (isValid(loading.node)) loading.string = `剧场贴纸\n正在展开素材 ${completed} / ${paths.size}`;
        }
      }));
      const hitAsset = await this.loadJson(`${this.resourcePrefix}/metadata/alpha-hit`);
      const hitData = hitAsset.json as unknown as { schemaVersion: string; masks: Record<string, AlphaMask> };
      if (hitData.schemaVersion !== 'alpha-hit-rle-v1') throw new Error('alpha 点击数据格式不匹配');
      this.hitMasks = new Map(Object.entries(hitData.masks));
      this.hitMasks = new Map(Object.entries(hitData.masks));
      try { this.toolFrame = await this.loadFrame(`resources/${this.tweezersResource}.png`); }
      catch { this.toolFrame = null; }
      if (!this.alive || !isValid(this.node)) return;
      loading.node.destroy();
      this.restoreProgress();
      this.unsubscribe = this.session.subscribe((_snapshot, event) => {
        if (['placed', 'undo', 'transition-finished', 'restored'].includes(event.type)) this.persist();
        if (event.type === 'undo' || event.type === 'transition-finished') this.page = 0;
        this.refresh();
      });
      this.booted = true;
      this.relayout();
      this.setCamera(this.cameraForBlock(this.session.getSnapshot().activeBlockId));
      this.refresh();
      if (this.session.getSnapshot().phase === 'transitioning') void this.runTour();
    } catch (error) {
      if (this.alive && this.ui && isValid(this.ui)) {
        this.destroyChildren(this.ui);
        this.makeLabel(this.ui, `素材尚未就绪\n${String(error)}\n请核对 resources 导入路径。`, 18, 340, 240);
      }
    }
  }

  private buildRoot(): void {
    this.root = this.makeNode(this.node, 'TheatreRoot', view.getVisibleSize().width, view.getVisibleSize().height);
    const stretch = this.root.addComponent(Widget);
    stretch.isAlignTop = stretch.isAlignBottom = stretch.isAlignLeft = stretch.isAlignRight = true;
    stretch.top = stretch.bottom = stretch.left = stretch.right = 0;
