/** Pure source-coordinate math; no engine dependency and no raster modification. */
export interface Point2 { x: number; y: number }
export interface Bounds { x: number; y: number; width: number; height: number }
export interface CameraPose { x: number; y: number; scale: number }
export interface LogicalTransform {
  position: Point2;
  sourceSize: { width: number; height: number };
  anchor: Point2;
  scale: number;
  rotation: number;
}
export interface FixedAttachment {
  stickerId: string;
  offset: Point2;
  inheritTransform: boolean;
}
export interface AttachableTransform extends LogicalTransform { attachment?: FixedAttachment }
export const clamp = (value: number, lo: number, hi: number): number => Math.max(lo, Math.min(hi, value));
export const smooth = (t: number): number => { const v = clamp(t, 0, 1); return v * v * (3 - 2 * v); };
export const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;

export function transformedPoint(owner: LogicalTransform, local: Point2): Point2 {
  const a = owner.rotation * Math.PI / 180;
  const x = (local.x - owner.anchor.x * owner.sourceSize.width) * owner.scale;
  const y = (local.y - owner.anchor.y * owner.sourceSize.height) * owner.scale;
  return { x: owner.position.x + x * Math.cos(a) - y * Math.sin(a),
    y: owner.position.y + x * Math.sin(a) + y * Math.cos(a) };
}

export function inversePoint(owner: LogicalTransform, world: Point2): Point2 {
  const a = owner.rotation * Math.PI / 180;
  const x = world.x - owner.position.x;
  const y = world.y - owner.position.y;
  return { x: (x * Math.cos(a) + y * Math.sin(a)) / owner.scale + owner.anchor.x * owner.sourceSize.width,
    y: (-x * Math.sin(a) + y * Math.cos(a)) / owner.scale + owner.anchor.y * owner.sourceSize.height };
}

/** Fixed tools follow their support's full pivot, rotation and uniform scale. */
export function fixedWorldTransform(fixed: AttachableTransform,
  owners: readonly (LogicalTransform & { stickerId: string })[]): LogicalTransform {
  const attachment = fixed.attachment;
  if (!attachment?.inheritTransform) return fixed;
  const support = owners.find(owner => owner.stickerId === attachment.stickerId);
  if (!support) return fixed;
  return { position: transformedPoint(support, attachment.offset), sourceSize: fixed.sourceSize,
    anchor: fixed.anchor, scale: support.scale * fixed.scale, rotation: support.rotation + fixed.rotation };
}

export function transformedBounds(owner: LogicalTransform): Bounds {
  const points = [{ x: 0, y: 0 }, { x: owner.sourceSize.width, y: 0 },
    { x: 0, y: owner.sourceSize.height }, { x: owner.sourceSize.width, y: owner.sourceSize.height }]
    .map(point => transformedPoint(owner, point));
  const xs = points.map(p => p.x); const ys = points.map(p => p.y);
  return { x: Math.min(...xs), y: Math.min(...ys), width: Math.max(...xs) - Math.min(...xs),
    height: Math.max(...ys) - Math.min(...ys) };
}

/** Camera includes both the geographical corner and all complete edited objects. */
export function cameraContentBounds(bounds: Bounds, owners: LogicalTransform[], padding = 14): Bounds {
  const objects = owners.map(transformedBounds);
  const x = Math.min(bounds.x, ...objects.map(b => b.x - padding));
  const y = Math.min(bounds.y, ...objects.map(b => b.y - padding));
  const right = Math.max(bounds.x + bounds.width, ...objects.map(b => b.x + b.width + padding));
  const bottom = Math.max(bounds.y + bounds.height, ...objects.map(b => b.y + b.height + padding));
  return { x, y, width: right - x, height: bottom - y };
}

/** Source origin is top-left, UI origin is board center and positive Y points up. */
export function fitCamera(bounds: Bounds, viewport: { width: number; height: number }, padding = 16): CameraPose {
  const scale = Math.max(0.001, Math.min(Math.max(1, viewport.width - padding * 2) / bounds.width,
    Math.max(1, viewport.height - padding * 2) / bounds.height));
  return { x: -(bounds.x + bounds.width / 2) * scale,
    y: (bounds.y + bounds.height / 2) * scale, scale };
}

/** Keep normal corner views inside the image; edited out-of-image objects remain reachable. */
export function clampCameraToScene(camera: CameraPose, required: Bounds,
  viewport: { width: number; height: number }, scene: { width: number; height: number }): CameraPose {
  if (required.x < 0 || required.y < 0 || required.x + required.width > scene.width
    || required.y + required.height > scene.height) return { ...camera };
  const halfW = viewport.width / (2 * camera.scale); const halfH = viewport.height / (2 * camera.scale);
  const cx = halfW * 2 >= scene.width ? scene.width / 2 : clamp(-camera.x / camera.scale, halfW, scene.width - halfW);
  const cy = halfH * 2 >= scene.height ? scene.height / 2 : clamp(camera.y / camera.scale, halfH, scene.height - halfH);
  return { x: -cx * camera.scale, y: cy * camera.scale, scale: camera.scale };
}

export function sourceToBoard(point: Point2, camera: CameraPose): Point2 {
  return { x: camera.x + point.x * camera.scale, y: camera.y - point.y * camera.scale };
}
export function boardToSource(point: Point2, camera: CameraPose): Point2 {
  return { x: (point.x - camera.x) / camera.scale, y: (camera.y - point.y) / camera.scale };
}

/** Left edge stays attached; uncompressed strips descend as contact travels left→right. */
export function pressStripLift(normalizedX: number, progress: number, height: number): number {
  const x = clamp(normalizedX, 0, 1);
  const contact = smooth((progress * 1.32 - x) / 0.32);
  const unpressed = 1 - contact;
  return height * 0.18 * unpressed * Math.sin(x * Math.PI / 2);
}

export function pressStrip(normalizedX: number, progress: number, height: number): { lift: number; angle: number; widthScale: number } {
  // Rotating or narrowing separate strips tears the illustration into a squeezed fan.
  return { lift: pressStripLift(normalizedX, progress, height), angle: 0, widthScale: 1 };
}

/** Small pickup fold restricted to the last 26% of the paper; no whole-object scaling. */
export function pickupStrip(normalizedX: number, progress: number, height: number): { lift: number; angle: number; widthScale: number } {
  const curl = smooth((normalizedX - 0.74) / 0.26) * Math.sin(clamp(progress, 0, 1) * Math.PI);
  return { lift: height * 0.075 * curl, angle: 10 * curl, widthScale: Math.max(0.96, Math.cos(curl * 0.2)) };
}

