  const asset = (key: any) => typeof key === 'string' && key.startsWith('resources/') && !key.split('/').includes('..') && !key.includes(':') && !key.includes('\\');
  if (!size(value.scene) || !asset(value.scene?.baseAssetKey) || !asset(value.scene?.referenceAssetKey)) errors.push('scene dimensions and artwork keys are required');
  if (value.scene?.basePatches !== undefined && !Array.isArray(value.scene.basePatches)) errors.push('basePatches must be an array');
  else for (const p of value.scene?.basePatches || []) if (!p || !asset(p.assetKey) || !point(p.position) || !size(p.sourceSize) || !size(p.size)) errors.push('invalid background repair tile');
  if (!Number.isSafeInteger(value.layoutRevision) || value.layoutRevision < 1) errors.push('renderable layoutRevision must be a positive integer');
  if (!Array.isArray(value.fixedLayers) || !Array.isArray(value.renderOrder) || !Array.isArray(value.stickers)) return [...errors, 'fixedLayers, renderOrder and stickers are required'];
  if (!value.stickers.length) errors.push('a renderable scene must contain stickers');
  for (const b of value.geoBlocks || []) {
    if (!b || !rect(b.bounds) || !rect(b.cameraBounds) || !Array.isArray(b.polygon) || b.polygon.length < 3 || !b.polygon.every(polygonPoint)) errors.push('geometric blocks require valid bounds, camera bounds and polygons');
  }
  const parts = new Map<string, any>();
  const logical = new Map<string, any>();
  const fixed = new Map<string, any>();
  for (const s of value.stickers) {
    if (!s || !asset(s.assetKey) || !size(s.sourceSize)) { errors.push('invalid sticker artwork'); continue; }
    logical.set(s.stickerId, s);
    if (!Array.isArray(s.renderParts) || !s.renderParts.length) { errors.push(`${s.stickerId} requires complete renderParts`); continue; }
    for (const p of s.renderParts) {
      if (!p || typeof p.partId !== 'string' || parts.has(p.partId) || !asset(p.assetKey) || !size(p.sourceSize) || !point(p.offset) || !Number.isSafeInteger(p.layerIndex) || !dependencies(p.requiresAssetIds)) errors.push(`${s.stickerId} invalid render part`);
      else parts.set(p.partId, p);
    }
  }
  for (const f of value.fixedLayers) {
    if (!f || typeof f.fixedId !== 'string' || fixed.has(f.fixedId) || !asset(f.assetKey) || !size(f.sourceSize) || !point(f.position) || !point(f.anchor) || !validNumber(f.scale) || f.scale <= 0 || !validNumber(f.rotation) || !Number.isSafeInteger(f.layerIndex) || !dependencies(f.requiresAssetIds)) errors.push('invalid fixed layer');
    else fixed.set(f.fixedId, f);
    if (f?.attachment && (!point(f.attachment.offset) || !logical.has(f.attachment.stickerId) || f.attachment.inheritTransform !== true || !Array.isArray(f.requiresAssetIds) || !f.requiresAssetIds.includes(f.attachment.stickerId))) errors.push('invalid fixed-layer attachment');
  }
  const keys = new Set<string>(), orders = new Set<number>();
  for (const e of value.renderOrder) {
    if (!e || !['fixed', 'stickerPart'].includes(e.kind) || !Number.isSafeInteger(e.layerIndex) || !Number.isSafeInteger(e.placementOrder) || e.placementOrder <= 0 || orders.has(e.placementOrder)) { errors.push('invalid global paint order'); continue; }
    orders.add(e.placementOrder);
    const key = e.kind === 'fixed' ? `fixed:${e.fixedId}` : `part:${e.partId}`;
    const target = e.kind === 'fixed' ? fixed.get(e.fixedId) : parts.get(e.partId);
    if (!target || keys.has(key) || target.placementOrder !== e.placementOrder || target.layerIndex !== e.layerIndex) errors.push(`invalid paint entry ${key}`);
    if (e.kind === 'stickerPart' && !logical.get(e.stickerId)?.renderParts?.some((p: any) => p.partId === e.partId)) errors.push('paint owner mismatch');
    keys.add(key);
  }
  if (keys.size !== parts.size + fixed.size) errors.push('global painter queue must include every part and fixed layer exactly once');
  if (errors.length) return errors;
  if (source) {
    const equal = (a: any, b: any) => JSON.stringify(a) === JSON.stringify(b);
    if (value.sceneId !== source.sceneId || !equal([value.scene?.width, value.scene?.height, value.scene?.baseAssetKey, value.scene?.referenceAssetKey, value.scene?.basePatches], [source.scene.width, source.scene.height, source.scene.baseAssetKey, source.scene.referenceAssetKey, source.scene.basePatches])) errors.push('import cannot replace scene artwork');
    const srcIds = source.stickers.map((s: any) => s.stickerId).sort();
    if (!equal([...logical.keys()].sort(), srcIds)) errors.push('import must retain the original logical sticker inventory');
    for (const original of source.stickers) {
      const s = logical.get(original.stickerId);
      if (!s || s.assetKey !== original.assetKey || !equal(s.sourceSize, original.sourceSize)) { errors.push('import cannot replace sticker pixels or dimensions'); continue; }
      if (!Array.isArray(s.renderParts) || s.renderParts.length !== original.renderParts.length) { errors.push('import cannot remove multipart geometry'); continue; }
      for (const oldPart of original.renderParts) {
        const p = s.renderParts.find((p: any) => p.partId === oldPart.partId);
        if (!p || p.assetKey !== oldPart.assetKey || !equal(p.offset, oldPart.offset) || !equal(p.sourceSize, oldPart.sourceSize)) errors.push('import cannot replace part pixels, offsets or dimensions');
      }
    }
    if (!equal([...fixed.keys()].sort(), source.fixedLayers.map((f: any) => f.fixedId).sort())) errors.push('import must retain fixed environment layers');
    for (const f of source.fixedLayers) {
      const candidate = fixed.get(f.fixedId);
      if (!candidate || !equal([candidate.assetKey, candidate.sourceSize, candidate.position, candidate.anchor, candidate.scale, candidate.rotation, candidate.requiresAssetIds, candidate.attachment], [f.assetKey, f.sourceSize, f.position, f.anchor, f.scale, f.rotation, f.requiresAssetIds, f.attachment])) errors.push('import cannot alter fixed environment artwork');
    }
    if (!equal((value.geoBlocks || []).map((b: any) => b.blockId).sort(), source.geoBlocks.map((b: any) => b.blockId).sort())) errors.push('import must retain the known geometric blocks');
  }
  return errors;
}
import { GameLayout, StickerPlacement } from '../../core/GameSession';
import { Point2, AttachableTransform, inversePoint, fixedWorldTransform } from './TheatreGeometry';
export interface AlphaMask { width: number; height: number; runs: number[] }
export type AlphaIndex = ReadonlyMap<string, AlphaMask>;

/** Binary alpha runs refer to canonical pixels, never to source-visible audit masks. */
export function alphaAt(masks: AlphaIndex, file: string, x: number, y: number): boolean {
  const mask = masks.get(file);
  if (!mask || x < 0 || y < 0 || x >= mask.width || y >= mask.height) return false;
  const index = Math.floor(y) * mask.width + Math.floor(x); let lo = 0; let hi = mask.runs.length / 2 - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >>> 1; const start = mask.runs[mid * 2]; const length = mask.runs[mid * 2 + 1];
    if (index < start) hi = mid - 1; else if (index >= start + length) lo = mid + 1; else return true;
  }
  return false;
}

/** Front hands and attached tools select their logical group; static foreground blocks picking. */
export function pickVisibleSticker(layout: GameLayout, placed: ReadonlySet<string>, world: Point2,
  masks: AlphaIndex): StickerPlacement | undefined {
  for (const entry of [...(layout.renderOrder ?? [])].sort((a, b) => b.placementOrder - a.placementOrder)) {
    if (entry.kind === 'fixed') {
      const fixed = layout.fixedLayers?.find(f => f.fixedId === entry.fixedId);
      if (!fixed) continue;
      const requires = fixed.requiresAssetIds as string[];
      if (!(requires ?? []).every(id => placed.has(id))) continue;
      const attached = fixed as unknown as AttachableTransform;
      const p = inversePoint(fixedWorldTransform(attached, layout.stickers), world);
      if (alphaAt(masks, String(fixed.assetKey), p.x, p.y)) {
        const ownerId = attached.attachment?.stickerId;
        return ownerId && placed.has(ownerId) ? layout.stickers.find(owner => owner.stickerId === ownerId) : undefined;
      }
    } else {
      if (!placed.has(entry.stickerId!)) continue;
      const owner = layout.stickers.find(s => s.stickerId === entry.stickerId);
      const part = owner?.renderParts?.find(p => p.partId === entry.partId);
      if (!owner || !part) continue;
      const p = inversePoint(owner, world);
      if (alphaAt(masks, String(part.assetKey), p.x - part.offset.x, p.y - part.offset.y)) return owner;
    }
  }
  return undefined;
}
