import { _decorator, Sprite, UITransform } from 'cc';
import type { IAssembler, RenderData } from 'cc';
import { pressPaperPoint } from './TheatreGeometry';
import type { Point2 } from './TheatreGeometry';

const { ccclass } = _decorator;

function makeIndices(columns: number): Uint16Array {
  const indices = new Uint16Array(columns * 6);
  for (let column = 0; column < columns; column++) {
    const vertex = column * 2;
    const index = column * 6;
    // Each adjacent pair of columns shares its bottom and top vertices.
    indices[index] = vertex;
    indices[index + 1] = vertex + 2;
    indices[index + 2] = vertex + 1;
    indices[index + 3] = vertex + 2;
    indices[index + 4] = vertex + 3;
    indices[index + 5] = vertex + 1;
  }
  return indices;
}

/** One continuous paper surface, using the source SpriteFrame and Sprite material. */
@ccclass('PaperMeshSprite')
export class PaperMeshSprite extends Sprite {
  private ownerWidth = 1;
  private ownerHeight = 1;
  private offsetX = 0;
  private columns = 48;
  private indices = makeIndices(48);
  private pressing = false;
  private progress = 1;
  private readonly point: Point2 = { x: 0, y: 0 };
  private transform: UITransform | null = null;

  private static readonly paperAssembler: IAssembler = {
    createData(component) {
      return (component as PaperMeshSprite).createMeshData();
    },
    updateRenderData(component) {
      const paper = component as PaperMeshSprite;
      const data = paper.renderData;
      const frame = paper.spriteFrame;
      if (!data || !frame) return;
      // Preserve original UVs; this assembler never enters the dynamic atlas.
      paper.updateMeshUVs();
      if (data.vertDirty) paper.updateMeshVertices();
      data.updateRenderData(paper, frame);
    },
    updateUVs(component) {
      (component as PaperMeshSprite).updateMeshUVs();
    },
    updateColor(component) {
      (component as PaperMeshSprite).updateMeshColor();
    },
    fillBuffers(component) {
      (component as PaperMeshSprite).fillMeshBuffers();
    },
  };

  configurePaper(ownerWidth: number, ownerHeight: number, offsetX = 0, columns = 48): void {
    if (!Number.isFinite(ownerWidth) || ownerWidth <= 0
      || !Number.isFinite(ownerHeight) || ownerHeight <= 0
      || !Number.isFinite(offsetX) || !Number.isFinite(columns)) {
      throw new Error('纸张网格需要有效的完整贴纸尺寸与分片偏移');
    }
    const nextColumns = Math.max(1, Math.min(256, Math.round(columns)));
    this.ownerWidth = ownerWidth;
    this.ownerHeight = ownerHeight;
    this.offsetX = offsetX;
    if (this.columns !== nextColumns) {
      this.columns = nextColumns;
      this.indices = makeIndices(nextColumns);
      if (this.renderData) {
        this.destroyRenderData();
        this._flushAssembler();
      }
    }
    this.markForUpdateRenderData();
  }

  setPressProgress(progress: number): void {
    const next = Number.isFinite(progress) ? Math.max(0, Math.min(1, progress)) : 1;
    if (this.pressing && this.progress === next) return;
    this.pressing = true;
    this.progress = next;
    this.markForUpdateRenderData();
  }

  setPickupProgress(_progress: number): void {
    // Pickup remains flat; the held paper's node supplies translation/rotation.
    this.resetFlat();
  }

  resetFlat(): void {
    if (!this.pressing) return;
    this.pressing = false;
    this.progress = 1;
    this.markForUpdateRenderData();
  }

  protected _flushAssembler(): void {
    const assembler = PaperMeshSprite.paperAssembler;
    if (this._assembler !== assembler) {
      this.destroyRenderData();
      this._assembler = assembler;
    }
    if (!this.renderData) {
      const data = this.createMeshData();
      data.material = this.getRenderMaterial(0);
      this.markForUpdateRenderData();
      this.updateMeshUVs();
      this._updateColor();
    }
  }

  private createMeshData(): RenderData {
    const data = this.requestRenderData();
    const vertexCount = (this.columns + 1) * 2;
    data.dataLength = vertexCount;
    data.resize(vertexCount, this.indices.length);
    // Native uses this index buffer; web appends the same indices below.
    data.chunk.setIndexBuffer(this.indices);
    return data;
  }

  private updateMeshVertices(): void {
    const data = this.renderData;
    if (!data) return;
    const transform = this.transform ?? (this.transform = this.node.getComponent(UITransform));
    if (!transform) return;
    const width = transform.width;
    const height = transform.height;
    const anchorX = transform.anchorX * width;
    // Source Y starts at the top; Cocos anchorY is measured from the bottom.
    const top = (1 - transform.anchorY) * height;
    for (let column = 0; column <= this.columns; column++) {
      const localX = column * width / this.columns;
      for (let row = 0; row < 2; row++) {
        const localY = row === 0 ? height : 0;
        const vertex = data.data[column * 2 + row];
        if (this.pressing) {
          pressPaperPoint(this.offsetX + localX, localY,
            this.ownerWidth, this.ownerHeight, this.progress, this.point);
          vertex.x = this.point.x - this.offsetX - anchorX;
          vertex.y = top - this.point.y;
        } else {
          vertex.x = localX - anchorX;
          vertex.y = top - localY;
        }
        vertex.z = 0;
      }
    }
    // fillBuffers consumes this flag after applying the complete world matrix.
    data.vertDirty = true;
  }

  private updateMeshUVs(): void {
    const data = this.renderData;
    const frame = this.spriteFrame;
    if (!data || !frame) return;
    const uv = frame.uv;
    const buffer = data.chunk.vb;
    const stride = data.floatStride;
    for (let column = 0; column <= this.columns; column++) {
      const x = column / this.columns;
      const bottomU = uv[0] + (uv[2] - uv[0]) * x;
      const bottomV = uv[1] + (uv[3] - uv[1]) * x;
      const topU = uv[4] + (uv[6] - uv[4]) * x;
      const topV = uv[5] + (uv[7] - uv[5]) * x;
      for (let row = 0; row < 2; row++) {
        const index = column * 2 + row;
        const u = bottomU + (topU - bottomU) * row;
        const v = bottomV + (topV - bottomV) * row;
        const vertex = data.data[index];
        vertex.u = u; vertex.v = v;
        const offset = index * stride + 3;
        buffer[offset] = u; buffer[offset + 1] = v;
      }
    }
  }

  private updateMeshColor(): void {
    const data = this.renderData;
    if (!data) return;
    const buffer = data.chunk.vb;
    const color = this.color;

  private updateMeshColor(): void {
    const data = this.renderData;
    if (!data) return;
    const buffer = data.chunk.vb;
    const color = this.color;
    const red = color.r / 255;
    const green = color.g / 255;
    const blue = color.b / 255;
    const alpha = color.a / 255;
    for (let index = 0; index < data.dataLength; index++) {
      const offset = index * data.floatStride + 5;
      buffer[offset] = red; buffer[offset + 1] = green;
      buffer[offset + 2] = blue; buffer[offset + 3] = alpha;
      data.data[index].color.set(color);
    }
  }

  private fillMeshBuffers(): void {
    const data = this.renderData;
    if (!data) return;
    const chunk = data.chunk;
    if (this.node.hasChangedFlags || data.vertDirty) {
      const matrix = this.node.worldMatrix;
      const buffer = chunk.vb;
      const stride = data.floatStride;
      for (let index = 0; index < data.dataLength; index++) {
        const vertex = data.data[index];
        const x = vertex.x;
        const y = vertex.y;
        const w = matrix.m03 * x + matrix.m07 * y + matrix.m15;
        const inverseW = w ? 1 / w : 1;
        const offset = index * stride;
        buffer[offset] = (matrix.m00 * x + matrix.m04 * y + matrix.m12) * inverseW;
        buffer[offset + 1] = (matrix.m01 * x + matrix.m05 * y + matrix.m13) * inverseW;
        buffer[offset + 2] = (matrix.m02 * x + matrix.m06 * y + matrix.m14) * inverseW;
      }
      data.vertDirty = false;
    }
    const meshBuffer = chunk.meshBuffer;
    const indices = meshBuffer.iData;
    const vertexOffset = chunk.vertexOffset;
    const indexOffset = meshBuffer.indexOffset;
    for (let index = 0; index < this.indices.length; index++) {
      indices[indexOffset + index] = vertexOffset + this.indices[index];
    }
    meshBuffer.indexOffset += this.indices.length;
  }
}

